function LastNameFirstInit_Lab8(g, s_a, h, nsteps)

% Determine the number of state variables
N = length(g);

% Initialize the slopes array
slopes = zeros(4, N);

% Perform initial RK4 steps
for iter = 1:2
    state = s_a(iter,:);
    for c = 1:N
        slopes(1,c) = g{c}(state);
    end

    state = s_a(iter,:) + (h/2)*[1, slopes(1,:)];
    for c = 1:N
        slopes(2,c) = g{c}(state);
    end

    state = s_a(iter,:) + (h/2)*[1, slopes(2,:)];
    for c = 1:N
        slopes(3,c) = g{c}(state);
    end

    state = s_a(iter,:) + h*[1, slopes(3,:)];
    for c = 1:N
        slopes(4,c) = g{c}(state);
    end

    RK = (slopes(1,:) + 2*slopes(2,:) + 2*slopes(3,:) + slopes(4,:)) / 6;

    s_a(iter+1,:) = s_a(iter,:) + h*[1, RK];      
end

% Perform ABM4 steps
for iter = 3:nsteps

    % Predictor
    p_state = s_a(iter,:) + h*((55/24)*slopes(1,:) - (59/24)*slopes(2,:) + (37/24)*slopes(3,:) - (3/8)*slopes(4,:));

    % Corrector
    converged = false;
    while ~converged
        c_slopes = slopes(1:3,:);
        for c = 1:N
            c_slopes(4,c) = g{c}(p_state);
        end

        c_state = s_a(iter,:) + h*((9/24)*c_slopes(4,:) + (19/24)*c_slopes(1,:) - (5/24)*c_slopes(2,:) + (1/24)*c_slopes(3,:));

