            converged = true;
        end

        % Update predictor state
        p_state = c_state;
    end

    % Update state array and slopes
    s_a(iter+1,:) = c_state;
    slopes = [c_slopes(1:3,:) ; slopes(1,:)];

end

% Print final state
disp(['Final state: ', num2str(s_a(end,:))])

% Plot traces of dependent variables
for c = 1:N
    figure
    plot(s_a(:,1),s_a(:,c+1))
